async function copyInFrame({ src, dst, limit }) {
  const e = window.editor || (window.Asc || {}).editor;
  if (!e || typeof e.asc_copyWorksheet !== 'function') return { ok: false, outcome: 'asc_copyWorksheet-unavailable' };
  const names = () => { const n = e.asc_getWorksheetsCount(); const out = []; for (let i = 0; i < n; i += 1) out.push(e.asc_getWorksheetName(i)); return out; };
  const before = names();
  if (before.some(n => n.toLowerCase() === dst.toLowerCase())) return { ok: false, outcome: 'name-taken-at-dispatch', before };
  const index = before.indexOf(src);
  if (index < 0 || before.indexOf(src, index + 1) >= 0) return { ok: false, outcome: 'source-identity-at-dispatch', before };
  const state0 = { canEdit: typeof e.canEdit === 'function' ? e.canEdit() : null, globalLock: e.collaborativeEditing && typeof e.collaborativeEditing.getGlobalLock === 'function' ? e.collaborativeEditing.getGlobalLock() : null, protectedWorkbook: typeof e.asc_isProtectedWorkbook === 'function' ? e.asc_isProtectedWorkbook() : null };
  if (state0.canEdit !== true || state0.globalLock || state0.protectedWorkbook !== false) return { ok: false, outcome: 'precondition-blocked', state: state0 };
  const errors = [];
  const onError = (id, level) => errors.push({ id, level });
  try { e.asc_registerCallback('asc_onError', onError); } catch { errors.push({ id: 'callback-not-registered' }); }
  try { e.asc_copyWorksheet(-1, [dst], [index]); } catch (err) { return { ok: false, outcome: 'threw', error: String(err).slice(0, 200) }; }
  const t0 = Date.now();
  let after = names();
  while (Date.now() - t0 < limit && after.length === before.length) { await new Promise(res => setTimeout(res, 25)); after = names(); }
  try { e.asc_unregisterCallback('asc_onError', onError); } catch { /* nothing to remove */ }
  const hits = after.filter(n => n === dst).length;
  const ok = hits === 1 && after.length === before.length + 1 && errors.length === 0;
  return { ok, outcome: ok ? 'copied' : (after.length === before.length ? 'timeout-or-no-effect' : 'unexpected-result'), hits, errors, before, after };
}
